   "orig": "首先，D-膜是什么？弦论为什么需要它们？对第二个问题的基本回答是：它们使 I 型理论中出现的开弦有了着落（见 31.14 节）——开弦的两端必须各自停留在某个 D-膜上（图 31.16）。至于第一个问题：D-膜（或 D-q-膜）是一个 1+q 维的类时结构（即 q 个空间维加 1 个时间维），它是 11 维超引力的一个稳定解。（借助 M 理论的某种对偶，我们也可以把 D-膜看作弦/M 理论某个其他版本的方程的解。）基本上，它就是 31.14 节描述的那种某一维数（0、1、2、…或 9）的「膜」，并且是一个 BPS 态（见 31.15、31.16 节），因此它带有某种超对称的杨–米尔斯荷的集合，并在此约束下具有最低能量。D-膜出现在许多现代与弦有关的讨论中（例如黑洞熵，见 31.15 节）。人们往往把它们当作位于 1+9（或 1+10）维完整时空之中的经典客体。D 代表「Dirichlet」（狄利克雷），这是类比于被称为狄利克雷问题的那类边值问题——在那类问题中，有一个类时边界，数据被指定在它上面（此名得自法国著名数学家彼得·G·勒热纳·狄利克雷，1805—1859；回想 7.4 节的「狄利克雷级数」）。",
